# dc-4j0e.9: controlled Compatibility Mode observations in one owned Excel session.
# Cases is produced by calc-doc's write_legacy_excel_session_inputs test. Result is the only
# output needed by the coordinator. The temporary workbooks are generated by this job itself.
param($OwnedExcel, [string]$Cases, [string]$Result)
$ErrorActionPreference = 'Stop'
$app = $OwnedExcel
$cases = Get-Content -LiteralPath $Cases -Raw -Encoding utf8 | ConvertFrom-Json
$dir = Join-Path ([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($Result))) ('xls-compat-' + [guid]::NewGuid().ToString('N'))
[IO.Directory]::CreateDirectory($dir) | Out-Null
$path = Join-Path $dir 'compat.xls'
$modern = Join-Path $dir 'converted.xlsx'
$limitsPath = Join-Path $dir 'limits.xls'
$book = $null
$oldAlerts = $app.DisplayAlerts
$answers = [Collections.Generic.List[object]]::new()
$fatal = $null
$legacyBytes = $null; $modernBytes = $null; $limitsBytes = $null
function Probe([string]$name, [scriptblock]$action) {
    try { $v = & $action; $answers.Add(@{name=$name; ok=$true; value=$v}) }
    catch { $answers.Add(@{name=$name; ok=$false; error=$_.Exception.Message; hresult=$_.Exception.HResult}) }
}
function ReadCell($cell) {
    return @{formula=[string]$cell.Formula; formula2=$(try {[string]$cell.Formula2} catch {$null});
        value=$(try {if ($null -eq $cell.Value2) {$null} else {[string]$cell.Value2}} catch {$_.Exception.Message});
        text=[string]$cell.Text; number_format=[string]$cell.NumberFormat}
}
try {
    $app.DisplayAlerts = $false
    $book = $app.Workbooks.Add(-4167)
    $sheet = $book.Worksheets.Item(1)
    $sheet.Name = 'Cases'
    $sheet.Range('A1').Value2 = 1
    $sheet.Range('A65536').Value2 = 2
    $book.SaveAs($path, 56)
    $book.Close($false); $book = $null
    $book = $app.Workbooks.Open($path, 0, $false)
    $sheet = $book.Worksheets.Item(1)
    Probe 'metadata' { @{excel_version=[string]$app.Version; excel_build=[string]$app.Build;
        compatibility_mode=$book.Excel8CompatibilityMode; file_format=$book.FileFormat;
        application_calculation_version=$app.CalculationVersion; workbook_calculation_version=$book.CalculationVersion;
        title=[string]$app.Caption; window_caption=[string]$book.Windows.Item(1).Caption;
        full_name=[string]$book.FullName; check_compatibility=$book.CheckCompatibility;
        rows=$sheet.Rows.Count; columns=$sheet.Columns.Count} }
    $row = 1
    foreach ($case in $cases.formulas) {
        $id = [string]$case[0]; $formula = [string]$case[1]; $cell = $sheet.Cells.Item($row, 3)
        Probe ('formula/' + $id) { $cell.Formula = $formula; $cell.Calculate() | Out-Null; ReadCell $cell }
        $row++
    }
    Probe 'end_down' { [string]$sheet.Range('A1').End(-4121).Address($false,$false) }
    Probe 'end_down_full_column' { $sheet.Range('F1:F65536').Value2 = 1; [string]$sheet.Range('F1').End(-4121).Address($false,$false) }
    Probe 'resize_past_old_limit' { [string]$sheet.Range('A65536').Resize(2,1).Address($false,$false) }
    Probe 'fill_down_at_limit' { $sheet.Range('G65535').Value2 = 17; $sheet.Range('G65535:G65536').FillDown(); $sheet.Range('G65536').Value2 }
    Probe 'fill_down_past_limit' { $sheet.Range('G65535:G65537').FillDown(); [string]$sheet.Range('G65537').Value2 }
    Probe 'used_range_before_corner' { [string]$sheet.UsedRange.Address($false,$false) }
    Probe 'last_legacy_cell' { $sheet.Range('IV65536').Value2 = 'edge'; [string]$sheet.Cells.SpecialCells(11).Address($false,$false) }
    Probe 'spill_across_legacy_edge' { $c = $sheet.Range('B65536'); $c.Formula2 = '=SEQUENCE(2)'; $c.Calculate() | Out-Null; ReadCell $c }
    Probe 'palette_roundtrip_before' { $sheet.Range('D1').Interior.Color = 1193046; $sheet.Range('D1').Interior.Color }
    foreach ($n in @(8192,8193)) {
        Probe ('formula_length/' + $n) { $s = '=' + ('1+' * [int][math]::Floor(($n-2)/2)) + '1'; if ($s.Length -lt $n) { $s = '=+' + $s.Substring(1) }; $sheet.Range('D2').Formula = $s; ([string]$sheet.Range('D2').Formula).Length }
    }
    foreach ($n in @(7,64)) {
        Probe ('nesting/' + $n) { $s = '=' + ('ABS(' * $n) + '1' + (')' * $n); $sheet.Range('D3').Formula = $s; ReadCell $sheet.Range('D3') }
    }
    foreach ($n in @(30,255)) {
        Probe ('arguments/' + $n) { $s = '=SUM(' + ((@('1') * $n) -join ',') + ')'; $sheet.Range('D4').Formula = $s; ReadCell $sheet.Range('D4') }
    }
    foreach ($n in @(255,256)) {
        Probe ('formula_string_length/' + $n) { $sheet.Range('D5').Formula = '="' + ('x' * $n) + '"'; ReadCell $sheet.Range('D5') }
    }
    Probe 'column_width' { $sheet.Columns.Item(8).ColumnWidth = 255; @{set=255; read=$sheet.Columns.Item(8).ColumnWidth} }
    Probe 'column_width_over_limit' { $sheet.Columns.Item(8).ColumnWidth = 256; @{set=256; read=$sheet.Columns.Item(8).ColumnWidth} }
    Probe 'conditional_formats' {
        $rules = $sheet.Range('I1').FormatConditions
        $results = @()
        foreach ($n in 1..4) {
            try { $null = $rules.Add(1, 3, '1'); $results += @{attempt=$n; count=$rules.Count} }
            catch { $results += @{attempt=$n; error=$_.Exception.Message} }
        }
        return ,$results
    }
    Probe 'defined_name' { $n = $book.Names.Add('cx_name', '=Cases!$A$1'); @{name=[string]$n.Name; refers_to=[string]$n.RefersTo} }
    foreach ($n in @(255,256)) {
        Probe ('defined_name_length/' + $n) { $name = 'n' * $n; $item = $book.Names.Add($name, '=Cases!$A$1'); ([string]$item.Name).Length }
    }
    Probe 'legacy_table_rows' {
        $sheet.Range('J1').Value2 = 'Values'
        $table = $sheet.ListObjects.Add(1, $sheet.Range('J1:J65536'), $null, 1)
        @{rows=$table.Range.Rows.Count; address=[string]$table.Range.Address($false,$false)}
    }
    Probe 'legacy_table_grow_past_limit' { $t = $sheet.ListObjects.Item(1); $t.Resize($sheet.Range('J1:J65537')); [string]$t.Range.Address($false,$false) }
    Probe 'save_legacy' { $book.Save(); @{file_format=$book.FileFormat; full_name=[string]$book.FullName} }
    $book.Close($false); $book = $null
    $legacyBytes = [Convert]::ToBase64String([IO.File]::ReadAllBytes($path))
    $book = $app.Workbooks.Open($path, 0, $false); $sheet = $book.Worksheets.Item(1)
    $row = 1
    foreach ($case in $cases.formulas) { $cell = $sheet.Cells.Item($row, 3); Probe ('reopened/' + [string]$case[0]) { ReadCell $cell }; $row++ }
    Probe 'palette_roundtrip_after' { $sheet.Range('D1').Interior.Color }
    Probe 'convert_xlsx' { $book.SaveAs($modern, 51); @{file_format=$book.FileFormat; compatibility_mode=$book.Excel8CompatibilityMode; used_range=[string]$sheet.UsedRange.Address($false,$false)} }
    $row = 1
    foreach ($case in $cases.formulas) { $cell = $sheet.Cells.Item($row, 3); Probe ('converted/' + [string]$case[0]) { if ($book.FileFormat -ne 51) { throw 'Conversion to xlsx did not succeed' }; ReadCell $cell }; $row++ }
    $book.Close($false); $book = $null
    if (Test-Path -LiteralPath $modern) { $modernBytes = [Convert]::ToBase64String([IO.File]::ReadAllBytes($modern)) }
    # Use a separate generated workbook so a limit or save refusal cannot spoil the formula cases.
    Probe 'style_and_name_counts' {
        $limits = $null; $reopened = $null
        try {
            $limits = $app.Workbooks.Add(-4167)
            $limitSheet = $limits.Worksheets.Item(1); $limitSheet.Name = 'Limits'
            $limits.SaveAs($limitsPath, 56)
            $initialStyles = $limits.Styles.Count; $styleAdded = 0; $styleError = $null
            $styleMilestones = @()
            $clock = [Diagnostics.Stopwatch]::StartNew()
            foreach ($i in 1..4100) {
                if ($clock.Elapsed.TotalSeconds -ge 240) { $styleError = @{attempt=$i; message='Time budget reached'; hresult=$null}; break }
                try {
                    $style = $limits.Styles.Add(('cxstyle_{0:D5}' -f $i))
                    $style.Interior.Color = $i
                    $limitSheet.Cells.Item($i, 1).Style = [string]$style.Name
                    $styleAdded++
                    if ($i -in @(1000, 4000, 4001, 4100)) { $styleMilestones += @{added=$i; styles=$limits.Styles.Count} }
                } catch { $styleError = @{attempt=$i; message=$_.Exception.Message; hresult=$_.Exception.HResult}; break }
            }
            $nameAdded = 0; $nameError = $null; $nameMilestones = @()
            $clock.Restart()
            foreach ($i in 1..4100) {
                if ($clock.Elapsed.TotalSeconds -ge 240) { $nameError = @{attempt=$i; message='Time budget reached'; hresult=$null}; break }
                try {
                    $null = $limits.Names.Add(('cxname_{0:D5}' -f $i), '=Limits!$A$1')
                    $nameAdded++
                    if ($i -in @(1000, 4000, 4001, 4100)) { $nameMilestones += @{added=$i; names=$limits.Names.Count} }
                } catch { $nameError = @{attempt=$i; message=$_.Exception.Message; hresult=$_.Exception.HResult}; break }
            }
            $before = @{styles=$limits.Styles.Count; names=$limits.Names.Count}
            $saveError = $null
            try { $limits.Save() } catch { $saveError = $_.Exception.Message }
            $limits.Close($false); $limits = $null
            $after = $null; $openError = $null
            try {
                $reopened = $app.Workbooks.Open($limitsPath, 0, $true)
                $after = @{styles=$reopened.Styles.Count; names=$reopened.Names.Count}
                $reopened.Close($false); $reopened = $null
            } catch { $openError = $_.Exception.Message }
            if (Test-Path -LiteralPath $limitsPath) { $script:limitsBytes = [Convert]::ToBase64String([IO.File]::ReadAllBytes($limitsPath)) }
            @{initial_styles=$initialStyles; styles_added=$styleAdded; style_milestones=$styleMilestones; style_error=$styleError;
              names_added=$nameAdded; name_milestones=$nameMilestones; name_error=$nameError;
              before_save=$before; save_error=$saveError; after_reopen=$after; reopen_error=$openError}
        } finally {
            if ($limits) { try { $limits.Close($false) } catch {} }
            if ($reopened) { try { $reopened.Close($false) } catch {} }
        }
    }
} catch { $fatal = $_.Exception.ToString() }
finally {
    if ($book) { try { $book.Close($false) } catch {} }
    $app.DisplayAlerts = $oldAlerts
}
@{fatal=$fatal; cases=$answers.ToArray(); legacy_base64=$legacyBytes; converted_base64=$modernBytes; limits_base64=$limitsBytes;
    not_run=@('Ctrl+End keyboard action', 'style count up to 64000', 'name count above 4100', 'recalculation across saving versions',
        'compatibility checker findings')} | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $Result -Encoding utf8NoBOM
